<?php
declare(strict_types=1);ob_start();session_start();require dirname(__DIR__,2).'/config/config.php';
function ed_json(int $status,array $data):never{http_response_code($status);header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');if(ob_get_level())ob_clean();echo json_encode($data,JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE);exit;}
if(!signed_in())ed_json(401,['ok'=>false,'message'=>'Your session expired. Sign in again.']);require_sign_in();if(!empty($_SESSION['must_change_password']))ed_json(403,['ok'=>false,'message'=>'Change your password before continuing.']);$uid=(int)$_SESSION['user_id'];$role=(string)$_SESSION['role'];$leaders=['director','sub_director','headteacher'];if($role!=='hr'&&!in_array($role,$leaders,true))ed_json(403,['ok'=>false,'message'=>'Your role cannot access staff documents.']);$school=filter_var($_REQUEST['school_id']??null,FILTER_VALIDATE_INT);$staffId=filter_var($_REQUEST['user_id']??null,FILTER_VALIDATE_INT);if(!$school||!$staffId)ed_json(422,['ok'=>false,'message'=>'Choose a school and staff member.']);$db=db();$q=$db->prepare('SELECT 1 FROM school_memberships WHERE user_id=? AND school_id=?');$q->execute([$uid,$school]);if(!$q->fetchColumn())ed_json(403,['ok'=>false,'message'=>'That school is outside your access.']);$roles="'admin','director','sub_director','headteacher','head_academic','department_head','assistant_academic','examination_officer','teacher','driver','hr','storekeeper','bursar'";$q=$db->prepare("SELECT 1 FROM school_memberships m JOIN users u ON u.id=m.user_id WHERE m.school_id=? AND m.user_id=? AND u.role IN ($roles)");$q->execute([$school,$staffId]);if(!$q->fetchColumn())ed_json(404,['ok'=>false,'message'=>'Staff account not found in this school.']);
$storage=dirname(__DIR__,2).DIRECTORY_SEPARATOR.'storage'.DIRECTORY_SEPARATOR.'staff_documents';
if($_SERVER['REQUEST_METHOD']==='GET'&&($_GET['action']??'')==='download'){$id=filter_var($_GET['id']??null,FILTER_VALIDATE_INT);if(!$id)ed_json(422,['ok'=>false,'message'=>'Choose a document.']);$q=$db->prepare('SELECT original_name,stored_name,mime_type,byte_size FROM employee_documents WHERE id=? AND school_id=? AND user_id=?');$q->execute([$id,$school,$staffId]);$doc=$q->fetch();if(!$doc)ed_json(404,['ok'=>false,'message'=>'Document not found.']);$base=realpath($storage);$path=$base?realpath($storage.DIRECTORY_SEPARATOR.$doc['stored_name']):false;if(!$base||!$path||!str_starts_with($path,$base.DIRECTORY_SEPARATOR)||!is_file($path))ed_json(404,['ok'=>false,'message'=>'Stored document is unavailable.']);while(ob_get_level())ob_end_clean();header('Content-Type: '.$doc['mime_type']);header('Content-Length: '.(int)$doc['byte_size']);header('Content-Disposition: attachment; filename="staff-document"; filename*=UTF-8\'\''.rawurlencode((string)$doc['original_name']));header('X-Content-Type-Options: nosniff');header('Cache-Control: private, no-store');readfile($path);exit;}
if($_SERVER['REQUEST_METHOD']==='GET'){$q=$db->prepare('SELECT d.id,d.category,d.original_name,d.mime_type,d.byte_size,d.created_at,u.name uploader FROM employee_documents d JOIN users u ON u.id=d.uploaded_by WHERE d.school_id=? AND d.user_id=? ORDER BY d.created_at DESC,d.id DESC');$q->execute([$school,$staffId]);ed_json(200,['ok'=>true,'data'=>['documents'=>$q->fetchAll(),'can_upload'=>$role==='hr']]);}
if($_SERVER['REQUEST_METHOD']!=='POST'||$role!=='hr')ed_json(403,['ok'=>false,'message'=>'Only school HR can upload staff documents.']);verify_csrf();$category=(string)($_POST['category']??'other');if(!in_array($category,['contract','qualification','identity','other'],true))ed_json(422,['ok'=>false,'message'=>'Choose a valid document category.']);$file=$_FILES['document']??null;if(!is_array($file)||($file['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK)ed_json(422,['ok'=>false,'message'=>'Choose a valid document to upload.']);$size=(int)($file['size']??0);$tmp=(string)($file['tmp_name']??'');if($size<1||$size>10*1024*1024||!is_uploaded_file($tmp)||filesize($tmp)!==$size)ed_json(413,['ok'=>false,'message'=>'Documents must be no larger than 10 MB.']);if(!class_exists('finfo'))ed_json(500,['ok'=>false,'message'=>'Secure file validation is unavailable.']);$finfo=new finfo(FILEINFO_MIME_TYPE);$mime=(string)$finfo->file($tmp);if(!in_array($mime,['application/pdf','image/jpeg','image/png'],true))ed_json(415,['ok'=>false,'message'=>'Only PDF, JPEG, and PNG documents are accepted.']);$name=trim(basename(str_replace('\\','/',(string)($file['name']??''))));$name=mb_substr(preg_replace('/[\x00-\x1F\x7F]/u','',$name)??'document',0,255);if($name==='')$name='document';if(!is_dir($storage)&&!mkdir($storage,0700,true)&&!is_dir($storage))ed_json(500,['ok'=>false,'message'=>'Secure document storage is unavailable.']);$stored=bin2hex(random_bytes(32));$target=$storage.DIRECTORY_SEPARATOR.$stored;if(!move_uploaded_file((string)$file['tmp_name'],$target))ed_json(500,['ok'=>false,'message'=>'The document could not be stored.']);@chmod($target,0600);try{$db->beginTransaction();$q=$db->prepare('INSERT INTO employee_documents(school_id,user_id,category,original_name,stored_name,mime_type,byte_size,uploaded_by) VALUES(?,?,?,?,?,?,?,?)');$q->execute([$school,$staffId,$category,$name,$stored,$mime,$size,$uid]);$id=(int)$db->lastInsertId();$q=$db->prepare("INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,details) VALUES(?,'upload','employee_document',?,?)");$q->execute([$uid,$id,json_encode(['school_id'=>$school,'user_id'=>$staffId,'category'=>$category,'byte_size'=>$size],JSON_THROW_ON_ERROR)]);$db->commit();ed_json(200,['ok'=>true,'message'=>'Staff document uploaded.']);}catch(Throwable $e){if($db->inTransaction())$db->rollBack();if(is_file($target))@unlink($target);error_log('Employee document upload failed: '.$e->getMessage());ed_json(500,['ok'=>false,'message'=>'The document could not be recorded.']);}
